sys_script_include.script:
var CreateRunOnboardValueBuilderTask = Class.create();
CreateRunOnboardValueBuilderTask.prototype = {
    initialize: function() {
        gs.log('Initializing CreateRunOnboardValueBuilderTask', 'CreateRunOnboardValueBuilderTask');
    },

    createOrUpdateTasks: function(categoryFilter) {
        gs.log('Starting createOrUpdateTasks method with category filter: ' + categoryFilter, 'CreateRunOnboardValueBuilderTask');
        var createdTasks = [];
        var updatedTasks = [];
        var processedProperties = [];

        gs.log('Fetching property: customrun.properties', 'CreateRunOnboardValueBuilderTask');
        var propertyName = 'customrun.properties'; // System property
        var kpiData = gs.getProperty(propertyName);

        if (!kpiData) {
            gs.error('Property "' + propertyName + '" is empty or not set.', 'CreateRunOnboardValueBuilderTask');
            return {
                createdTasks,
                updatedTasks,
                processedProperties
            };
        }

        processedProperties.push(propertyName); // Record processed property
        gs.info('Processing Property: ' + propertyName, 'CreateRunOnboardValueBuilderTask');

        try {
            gs.log('Parsing KPI data from property', 'CreateRunOnboardValueBuilderTask');
            var kpiCategories = JSON.parse(kpiData);

            // Filter categories based on the categoryFilter parameter if provided
            if (categoryFilter) {
                gs.log('Filtering categories by: ' + categoryFilter, 'CreateRunOnboardValueBuilderTask');
                var filteredCategories = [];

                for (var i = 0; i < kpiCategories.length; i++) {
                    if (kpiCategories[i].category &&
                        kpiCategories[i].category.toLowerCase() === categoryFilter.toLowerCase()) {
                        filteredCategories.push(kpiCategories[i]);
                        gs.log('Category match found: ' + kpiCategories[i].category, 'CreateRunOnboardValueBuilderTask');
                    }
                }

                if (filteredCategories.length === 0) {
                    gs.warning('No categories matched the filter: ' + categoryFilter, 'CreateRunOnboardValueBuilderTask');
                }

                kpiCategories = filteredCategories;
            }

            gs.log('Found ' + kpiCategories.length + ' categories to process', 'CreateRunOnboardValueBuilderTask');
            var userData = this.transform();

            for (var i = 0; i < kpiCategories.length; i++) {
                var category = kpiCategories[i];
                gs.log('Processing category [' + (i + 1) + '/' + kpiCategories.length + ']: ' + category.category, 'CreateRunOnboardValueBuilderTask');

                if (!category.category || !category.actions) {
                    gs.error('Invalid category format: ' + JSON.stringify(category), 'CreateRunOnboardValueBuilderTask');
                    continue;
                }

                gs.log('Category has ' + category.actions.length + ' actions to process', 'CreateRunOnboardValueBuilderTask');
                for (var j = 0; j < category.actions.length; j++) {
                    var action = category.actions[j];
                    gs.log('Processing action [' + (j + 1) + '/' + category.actions.length + ']: ' + action.type, 'CreateRunOnboardValueBuilderTask');

                    if (!action.type || !action.description || !action.short_description || !action.instruction) {
                        gs.error('Missing required fields for action: ' + JSON.stringify(action), 'CreateRunOnboardValueBuilderTask');
                        continue;
                    }

                    var finalInstruction = action.instruction;

                    // If category type is "User Management", handle user-specific actions
                    if (category.category.toLowerCase() === 'user management') {
                        gs.log('User Management category detected, processing user action: ' + action.type, 'CreateRunOnboardValueBuilderTask');

                        // Check if this is specifically an activation task
                        if (action.description.toLowerCase().indexOf('activate') !== -1 ||
                            action.type.toLowerCase().indexOf('activate') !== -1) {
                            gs.log('User activation task detected', 'CreateRunOnboardValueBuilderTask');
                            var activationList = userData.usersToActivate.map(function(p, index) {
                                return (index + 1) + '. ' + p.id + ' (' + p.description + ')';
                            }).join('\n');
                            finalInstruction += '\n\nUsers to Activate:\n' + (activationList || 'None');
                        }
                        // Check if this is specifically an upgrade task
                        else if (action.description.toLowerCase().indexOf('upgrade') !== -1 ||
                            action.type.toLowerCase().indexOf('upgrade') !== -1) {
                            gs.log('User upgrade task detected', 'CreateRunOnboardValueBuilderTask');
                            var upgradeList = userData.usersToUpgrade.map(function(p, index) {
                                return (index + 1) + '. ' + p.id + ' (' + p.description + ')';
                            }).join('\n');
                            finalInstruction += '\n\nUsers to Upgrade:\n' + (upgradeList || 'None');
                        }
                        // For general user management tasks, include both lists
                        else {
                            gs.log('General user management task detected', 'CreateRunOnboardValueBuilderTask');
                            var activationList = userData.usersToActivate.map(function(p, index) {
                                return (index + 1) + '. ' + p.id + ' (' + p.description + ')';
                            }).join('\n');
                            var upgradeList = userData.usersToUpgrade.map(function(p, index) {
                                return (index + 1) + '. ' + p.id + ' (' + p.description + ')';
                            }).join('\n');
                            finalInstruction += '\n\nUsers to Activate:\n' + (activationList || 'None') + '\n\nUsers to Upgrade:\n' + (upgradeList || 'None');
                        }

                        gs.log('Added user details to instruction, length: ' + finalInstruction.length, 'CreateRunOnboardValueBuilderTask');
                    }

                    // Check if a task with the same description exists
                    gs.log('Checking for existing task with description: ' + action.description, 'CreateRunOnboardValueBuilderTask');
                    var existingTask = new GlideRecord('samp_sp_vb_task');
                    existingTask.addQuery('description', action.description);
                    existingTask.addEncodedQuery('stateNOT IN2,-5,3,7'); // Active tasks
                    existingTask.query();

                    if (existingTask.next()) {
                        gs.log('Found existing task, updating: ' + existingTask.sys_id, 'CreateRunOnboardValueBuilderTask');
                        // Update existing task
                        existingTask.setValue('short_description', action.short_description);
                        existingTask.setValue('instructions', finalInstruction);
                        existingTask.update();
                        gs.info('Updated task for action: ' + action.type, 'CreateRunOnboardValueBuilderTask');
                        updatedTasks.push(action.type);
                    } else {
                        gs.log('No existing task found, creating new task', 'CreateRunOnboardValueBuilderTask');
                        // Create new task
                        var taskGr = new GlideRecord('samp_sp_vb_task');
                        taskGr.initialize();
                        taskGr.setValue('short_description', action.short_description);
                        taskGr.setValue('description', action.description);
                        taskGr.setValue('instructions', finalInstruction);

                        gs.log('Inserting new task record', 'CreateRunOnboardValueBuilderTask');
                        var taskId = taskGr.insert();
                        if (taskId) {
                            gs.info('Created task for action: ' + action.type + ' (Task ID: ' + taskId + ')', 'CreateRunOnboardValueBuilderTask');
                            createdTasks.push(action.type);
                            gs.log('Queueing event: sam.implementation.value.builder.task', 'CreateRunOnboardValueBuilderTask');
                            gs.eventQueue('sam.implementation.value.builder.task', taskGr, taskGr.sys_id);
                        } else {
                            gs.error('Failed to create task for action: ' + action.type, 'CreateRunOnboardValueBuilderTask');
                        }
                    }
                }
            }
        } catch (e) {
            gs.error('Error processing property "' + propertyName + '": ' + e.message, 'CreateRunOnboardValueBuilderTask');
            gs.log('Stack trace: ' + e.stack, 'CreateRunOnboardValueBuilderTask');
        }

        gs.log('Completed createOrUpdateTasks method. Created: ' + createdTasks.length +
            ', Updated: ' + updatedTasks.length + ', Properties processed: ' +
            processedProperties.length, 'CreateRunOnboardValueBuilderTask');

        return {
            createdTasks: createdTasks,
            updatedTasks: updatedTasks,
            processedProperties: processedProperties
        };
    },

